    const values = baseline.map((b) => b[key]).filter((v)              => v !== null).map((v) => (log ? Math.log(v) : v));
    if (value === null || values.length < 4) return null;
    const x = log ? Math.log(value) : value;
    return (x - mean(values) ) / Math.max(floor, sd(values) ?? floor);
